def read(n):return json.loads((R/n).read_text(encoding='utf-8'))
def dump(n,x):(R/n).write_text(json.dumps(x,ensure_ascii=False,indent=2,default=lambda v:v.item() if hasattr(v,'item') else str(v)),encoding='utf-8')
def main():
    main=read('tep_results.json');follow=read('calibration_followup.json');prior=json.loads((ROOT/'experiments/v3/results/risk_results.json').read_text());summary=[]
    for label,records in [('v3_reference',prior)]+[(s,[r for r in main+follow if r['strategy']==s]) for s in sorted({r['strategy'] for r in main+follow})]:
        summary.append({'strategy':label,'folds':len(records),'passes':sum(r['pass_risk'] for r in records),'mean_coverage':float(np.mean([r['coverage'] for r in records])),'min_coverage':min(r['coverage'] for r in records),'max_coverage':max(r['coverage'] for r in records),'FB_repeated_count':sum(r['FB'] for r in records),'NF_repeated_count':sum(r['NF'] for r in records),'maximum_FB_upper':max(r['FB_upper'] for r in records),'maximum_NF_upper':max(r['NF_upper'] for r in records)})
    dump('tep_summary.json',summary);pred=pd.read_csv(R/'calibration_predictions.csv');fault9=[]
    for name,g in pred[pred.fault==9].groupby('strategy'):fault9.append({'strategy':name,'repeated_fault9_evaluations':len(g),'benign':int(sum(g.route==0)),'fault':int(sum(g.route==1)),'abstain':int(sum(g.route==-1))})
    dump('fault9_dispositions.json',fault9)
    h=read('hai_results.json');h['scope']='Official normal training files plus labeled early attack files, later attack-file holdout. Official train2/train3 postdate evaluation; NOT strict chronological extrapolation. See hai_strict_results.json.';h['chronology_correction']='Added after timestamp audit; numerical outcomes unchanged.';dump('hai_results.json',h);strict=read('hai_strict_results.json');integrity=read('hai_integrity.json');components=read('hai_component_ablation.json')
    hai=[{'method':'v3_reference',**h['v3_same_cohort'],'detected_episodes':h['v3_same_cohort_episode_detected'],'total_episodes':h['episode_total']},{'method':'v4_official_file_split',**h['selected_heldout'],'detected_episodes':h['episode_detected'],'total_episodes':h['episode_total']},{'method':'v4_strict_past_only',**strict['selected_heldout'],'detected_episodes':strict['episode_detected'],'total_episodes':strict['episode_total']}];dump('hai_comparison.json',hai)
    bindings=read('calibration_bindings.json');scores=np.load(OUT/'data/tep_scores.npz');oldpred=pd.read_csv(ROOT/'experiments/v3/results/risk_predictions.csv');checks=[]
    for b in bindings:
        assert not set(scores['run'][b['calibration_indices']])&set(scores['run'][b['evaluation_indices']]);actual={(int(scores['fault'][i]),int(scores['run'][i])) for i in b['evaluation_indices']};old=oldpred[(oldpred.seed==b['seed'])&(oldpred.fold==b['fold'])];assert actual==set(zip(old.fault,old.run));checks.append(True)
    policy=read('hai_strict_frozen_policy.json');path=OUT/'models'/f"hai_strict_{policy['model']}.joblib";assert hashlib.sha256(path.read_bytes()).hexdigest()==policy['model_sha256'];assert strict['chronology_verified'] and strict['exact_training_heldout_feature_duplicates']==0
    model=joblib.load(path);assert model.n_features_in_==790 if policy['model']=='absolute_dynamic' else True
    dates=integrity['timestamp_ranges'];verification={'tep_same_outer_evaluation_examples':all(checks),'tep_calibration_evaluation_groups_disjoint':all(checks),'tep_followup_splits_checked':len(checks),'hai_selected_model_hash_verified':True,'hai_strict_chronology_verified':True,'hai_no_training_heldout_exact_feature_duplicates':True,'hai_no_attack_or_time_features':not integrity['attack_or_time_features'],'official_training_files_include_future_dates':True,'all_new_runs_retrospective':True,'llm_calls_this_round':0,'protocol_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.glob('*json')}};dump('verification.json',verification)
    selected=next(r for r in summary if r['strategy']=='guarded_margin_cal400');control=next(r for r in summary if r['strategy']=='fixed_nominal_same_calibration');small=next(r for r in summary if r['strategy']=='margin_cal100')
    claims={'recommended_experimental_direction':'Keep current-evidence numeric routing; use conservative calibration with adequate grouped calibration data; adapt HAI evidence representation using earlier labeled attack examples and verify actual chronology.','TEP':{'same_model_same_calibration_nominal':control,'same_model_same_calibration_margin':small,'larger_calibration_guarded':selected,'interpretation':'Improved observed constraint attainment through calibration and abstention, not a new accuracy model. Fifteen overlapping repeated evaluations do not prove universal risk control.','fault9_limitation':next(r for r in fault9 if r['strategy']=='guarded_margin_cal400')},'HAI':{'strict_past_only':strict['selected_heldout'],'episodes':[strict['episode_detected'],strict['episode_total']],'interpretation':'Supervised dataset adaptation on early attack labels; not unsupervised or zero-shot generalization. Strict chronology control preserves gains, but all data were previously exposed and the post-hoc control is exploratory.'},'not_supported':['New TEP temporal features improve fault9 discrimination','Previous-600-row context has an independent HAI gain','Aggregate risk pass implies fault9 safety','15/15 repeated passes imply a universal risk guarantee','History improves explanation quality or human usefulness']};dump('claim_assessment.json',claims)
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False});names=['fixed_nominal_same_calibration','margin_cal100','margin_cal200','margin_cal400','guarded_margin_cal400'];labels=['Nominal, 100 groups','Margin, 100 groups','Margin, 200 groups','Margin, 400 groups','Guarded margin, 400 groups'];chosen=[next(r for r in summary if r['strategy']==n) for n in names];fig,ax=plt.subplots(1,2,figsize=(11,4.5),layout='constrained');yy=np.arange(len(names));ax[0].barh(yy,[100*r['mean_coverage'] for r in chosen],color='#397aa8');ax[0].set(yticks=yy,yticklabels=labels,xlim=(0,105),xlabel='Mean automatic coverage (%)');ax[0].invert_yaxis();ax[1].barh(yy,[r['passes'] for r in chosen],color=['#bd5555' if r['passes']<15 else '#24826d' for r in chosen]);ax[1].set(yticks=yy,yticklabels=[],xlim=(0,17),xlabel='Outer evaluations passing both bounds (of 15)');ax[1].invert_yaxis()
