    fig,ax=plt.subplots(1,2,figsize=(10,4),layout='constrained');xx=np.arange(3);labels=['v3 reference','v4 official files','v4 past-only'];ax[0].bar(xx,[r['fault_recognized'] for r in hai],color=['#9caebf','#397aa8','#24826d']);ax[0].set(xticks=xx,xticklabels=labels,ylabel='Fault windows correctly recognized (of 41)',ylim=(0,45));ax[1].bar(xx,[r['detected_episodes'] for r in hai],color=['#9caebf','#397aa8','#24826d']);ax[1].set(xticks=xx,xticklabels=labels,ylabel='Attack episodes detected (of 17)',ylim=(0,19));fig.suptitle('HAI: identical test4/test5 windows and attack episodes');fig.savefig(R/'hai_optimization.png',dpi=170);plt.close(fig)
    chunks=['<h1>论文2：数据集适配优化 v4</h1><p>本轮为已知数据集上的回顾性优化。新增复杂特征、失败候选与时间戳审计问题均保留；没有把这些结果标为全新独立确认。未新增 LLM API 调用。</p>',f"<p><b>TEP：</b>同模型、同校准样本的名义目标对照通过 {control['passes']}/15 轮；预留余量后通过 {small['passes']}/15 轮。增加校准组数并采用更保守预算后通过 {selected['passes']}/15，平均覆盖率 {selected['mean_coverage']:.1%}。<b>HAI：</b>严格只使用过去数据的对照，在 test4/test5 检出 {strict['episode_detected']}/{strict['episode_total']} 个攻击事件，识别 {strict['selected_heldout']['fault_recognized']}/41 个故障窗口。</p>",'<img src="tep_optimization.png" width="1000"><img src="hai_optimization.png" width="900">']
    def table(title,rows):chunks.append('<h2>'+title+'</h2>'+pd.DataFrame(rows).to_html(index=False,escape=True))
