    table('HAI 同口径比较：test4/test5',hai);chunks.append('<p>官方 train2/train3 的日期晚于 test4/test5，官方文件划分实验不属于严格时间外推。严格对照重新拟合过去数据标准化器，仅用 train1 在2020-07-13之前的正常数据及更早的 test1/test2 标签训练；test3校准；test4/test5评估。严格对照是时间戳审计后追加，虽然拟合/校准/评估时间顺序正确，仍不是未见过的数据集确认。故障窗口相关、总攻击事件仅17个，不主张5%风险认证或未见攻击类型泛化。</p>')
    table('官方文件划分：全候选留出结果',[r for r in h['candidate_results'] if r['source']=='heldout']);table('官方文件划分：组件消融',[{'view':r['view'],**r['heldout']} for r in components]);table('严格过去数据对照：全候选留出结果',[r for r in strict['candidate_results'] if r['source']=='heldout']);chunks.append('<p>仅中心化动态特征在官方文件划分下已经达到与完整相对特征相近的效果，因此没有证据支持前序600秒上下文的独立增益。严格时间对照中，校准集选出的模型为 absolute_dynamic，保留此选择，没有按留出结果换成其他候选。训练使用较早攻击标签，因此性能提升不能归因于无监督方法本身。</p>')
